// Deterministic identity for installed runtime inputs; generated files are excluded.
import { createHash } from 'node:crypto'
import { readFileSync, readdirSync, realpathSync } from 'node:fs'
import { join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const LOADED_ROOT = realpathSync(resolve(fileURLToPath(new URL('../..', import.meta.url))))
const ID_PATTERN = /^[a-f0-9]{64}$/
const ROOT_FILES = ['package.json', 'cordis.patch.yml', 'lib/index.js', 'icon.svg', 'scripts/build-client.mjs']
const DIRECTORIES = ['src/client', 'src/host', 'src/shared', 'locale']
const EXCLUDED = new Set(['src/shared/build-id.js'])

export function computeBuildId(root) {
  const files = [...ROOT_FILES]
  const walk = (dir) => {
    for (const entry of readdirSync(join(root, dir), { withFileTypes: true })) {
      const name = `${dir}/${entry.name}`
      if (entry.isDirectory()) walk(name)
      else if (entry.isFile() && !EXCLUDED.has(name)) files.push(name)
      else if (!entry.isFile()) throw new Error('unsupported runtime entry')
    }
  }
  for (const dir of DIRECTORIES) walk(dir)
  files.sort()
  const hash = createHash('sha256')
  for (const name of files) {
    const bytes = readFileSync(join(root, ...name.split('/')))
    hash.update(`${Buffer.byteLength(name)}:${name}:${bytes.length}:`)
    hash.update(bytes)
  }
  return hash.digest('hex')
}

export function sha256File(path) {
  return createHash('sha256').update(readFileSync(path)).digest('hex')
}

export function inspectLocalBuild(profileDir, canReload, loadedRoot = LOADED_ROOT, runningId) {
  const unknown = (reason) => ({ runningId, installedId: null, state: 'unknown', canApply: false, reason })
  if (!ID_PATTERN.test(runningId)) return unknown('running-build-unknown')
  try {
    if (typeof profileDir !== 'string' || profileDir === '') return unknown('profile-unavailable')
    const installedRoot = realpathSync(join(profileDir, 'node_modules', 'dsh-next-message-predictor'))
    if (relative(installedRoot, loadedRoot) !== '' || relative(loadedRoot, installedRoot) !== '') return unknown('installation-moved')
    const manifest = JSON.parse(readFileSync(join(installedRoot, 'lib', 'build-manifest.json'), 'utf8'))
    if (!ID_PATTERN.test(manifest.buildId) || !ID_PATTERN.test(manifest.clientSha256) ||
      computeBuildId(installedRoot) !== manifest.buildId ||
      sha256File(join(installedRoot, 'lib', 'client.js')) !== manifest.clientSha256) return unknown('build-incomplete')
    const generated = readFileSync(join(installedRoot, 'src', 'shared', 'build-id.js'), 'utf8')
    if (!new RegExp(`^// Generated by scripts/build-client\\.mjs\\. Do not edit\\.\\r?\\nexport const PLUGIN_BUILD_ID = '${manifest.buildId}'\\r?\\n$`).test(generated) ||
      !readFileSync(join(installedRoot, 'lib', 'client.js'), 'utf8').includes(`const PLUGIN_BUILD_ID = '${manifest.buildId}'`)) return unknown('build-incomplete')
    const state = manifest.buildId === runningId ? 'current' : 'update-available'
    return { runningId, installedId: manifest.buildId, state, canApply: state === 'update-available' && canReload, reason: canReload ? '' : 'update-unavailable' }
  } catch {
    return unknown('build-unavailable')
  }
}

export async function applyBuildUpdate({ hmr, inspect, entryId, targetBuildId, signal, isActive = () => true }) {
  if (typeof hmr?.runExclusive !== 'function' || typeof hmr?.reconcileProfile !== 'function') return 'update-unavailable'
  try {
    return await hmr.runExclusive(async () => {
      const current = inspect()
      if (!isActive() || signal?.aborted || current.state !== 'update-available' || current.installedId !== targetBuildId || !current.canApply) return 'build-changed'
      const result = await hmr.reconcileProfile([entryId])
      if (!Array.isArray(result?.pending) || !Array.isArray(result?.warnings)) return 'reconcile-failed'
      if (result.restartReason || result.pending.length) return 'restart-required'
      if (result.warnings.length) return 'reconcile-failed'
      return ''
    })
  } catch {
    return 'reconcile-failed'
  }
}
